// Evaluate K_2d(L_left, L_right) -> K[4][10] stored row-major in k_out[40]
static inline void k_table_2d_eval(float L_left, float L_right, float *k_out) {
    float xl = (2.0f * L_left - K2D_H_MIN - K2D_H_MAX) / (K2D_H_MAX - K2D_H_MIN);
    float xr = (2.0f * L_right - K2D_H_MIN - K2D_H_MAX) / (K2D_H_MAX - K2D_H_MIN);
    float Tl[K2D_ORDER + 1], Tr[K2D_ORDER + 1];
    Tl[0] = 1.0f; Tr[0] = 1.0f;
    if (K2D_ORDER >= 1) {
        Tl[1] = xl; Tr[1] = xr;
    }
    for (int i = 2; i <= K2D_ORDER; i++) {
        Tl[i] = 2.0f * xl * Tl[i - 1] - Tl[i - 2];
        Tr[i] = 2.0f * xr * Tr[i - 1] - Tr[i - 2];
    }
    // Triangular Chebyshev terms: T_left[d-a] * T_right[a] for d=0..8
    float terms[45];
    terms[0] = Tl[0] * Tr[0];
    terms[1] = Tl[1] * Tr[0];
    terms[2] = Tl[0] * Tr[1];
    terms[3] = Tl[2] * Tr[0];
    terms[4] = Tl[1] * Tr[1];
    terms[5] = Tl[0] * Tr[2];
    terms[6] = Tl[3] * Tr[0];
    terms[7] = Tl[2] * Tr[1];
    terms[8] = Tl[1] * Tr[2];
    terms[9] = Tl[0] * Tr[3];
    terms[10] = Tl[4] * Tr[0];
    terms[11] = Tl[3] * Tr[1];
    terms[12] = Tl[2] * Tr[2];
    terms[13] = Tl[1] * Tr[3];
    terms[14] = Tl[0] * Tr[4];
    terms[15] = Tl[5] * Tr[0];
    terms[16] = Tl[4] * Tr[1];
    terms[17] = Tl[3] * Tr[2];
    terms[18] = Tl[2] * Tr[3];
    terms[19] = Tl[1] * Tr[4];
    terms[20] = Tl[0] * Tr[5];
    terms[21] = Tl[6] * Tr[0];
    terms[22] = Tl[5] * Tr[1];
    terms[23] = Tl[4] * Tr[2];
    terms[24] = Tl[3] * Tr[3];
    terms[25] = Tl[2] * Tr[4];
    terms[26] = Tl[1] * Tr[5];
    terms[27] = Tl[0] * Tr[6];
    terms[28] = Tl[7] * Tr[0];
    terms[29] = Tl[6] * Tr[1];
    terms[30] = Tl[5] * Tr[2];
    terms[31] = Tl[4] * Tr[3];
    terms[32] = Tl[3] * Tr[4];
    terms[33] = Tl[2] * Tr[5];
    terms[34] = Tl[1] * Tr[6];
    terms[35] = Tl[0] * Tr[7];
    terms[36] = Tl[8] * Tr[0];
    terms[37] = Tl[7] * Tr[1];
    terms[38] = Tl[6] * Tr[2];
    terms[39] = Tl[5] * Tr[3];
    terms[40] = Tl[4] * Tr[4];
    terms[41] = Tl[3] * Tr[5];
    terms[42] = Tl[2] * Tr[6];
    terms[43] = Tl[1] * Tr[7];
    terms[44] = Tl[0] * Tr[8];

    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 10; j++) {
            float sum = 0.0f;
            int base = (i * 10 + j) * 45;
            for (int t = 0; t < 45; t++) {
                sum += k_table_2d[base + t] * terms[t];
            }
            k_out[i * 10 + j] = sum;
        }
    }
}
// clang-format on
